jsonl:
{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["composer","after-note"]}}
{"op":"add","path":"/elements/composer","value":{"type":"Composer","props":{"headline":"Your trip, planned day by day, within budget","lede":"Tell us where, when and who - get a plan for each day and what it will cost.","runLabel":"Plan my trip","columns":"2"},"on":{"press":[{"action":"validateForm"},{"action":"run"}]},"children":["group-where","group-who","group-feel","group-else"]}}
{"op":"add","path":"/elements/group-where","value":{"type":"FieldGroup","props":{"title":"Where and when"},"children":["trip-title","city","country","dates","must-see"]}}
{"op":"add","path":"/elements/trip-title","value":{"type":"Input","props":{"label":"Trip name","name":"title","placeholder":"Long weekend in Lisbon","value":{"$bindState":"/inputs/request/title"},"checks":[{"type":"required","message":"Give the trip a name"}]},"children":[]}}
{"op":"add","path":"/elements/city","value":{"type":"Input","props":{"label":"City","name":"city","value":{"$bindState":"/inputs/request/stay/city"},"checks":[{"type":"required","message":"Which city?"}]},"children":[]}}
{"op":"add","path":"/elements/country","value":{"type":"Select","props":{"label":"Country","name":"country","options":["France","Italy","Japan","Portugal","Spain","United States"],"value":{"$bindState":"/inputs/request/stay/country"},"checks":[{"type":"required","message":"Pick a country"}]},"children":[]}}
{"op":"add","path":"/elements/dates","value":{"type":"DateRange","props":{"label":"Dates","from":{"$bindState":"/inputs/request/stay/arriving_on"},"to":{"$bindState":"/inputs/request/stay/leaving_on"}},"children":[]}}
{"op":"add","path":"/elements/must-see","value":{"type":"Chips","props":{"label":"Can't miss","placeholder":"Add a place, press Enter","value":{"$bindState":"/inputs/request/stay/must_see"}},"children":[]}}
{"op":"add","path":"/elements/group-who","value":{"type":"FieldGroup","props":{"title":"Who and how much"},"children":["travellers","with-children","budget","currency"]}}
{"op":"add","path":"/elements/travellers","value":{"type":"CompactList","props":{"label":"Travellers","items":{"$bindState":"/inputs/request/travellers"},"primary":"name","secondary":["age","dietary"],"addLabel":"Add a traveller"},"children":[]}}
{"op":"add","path":"/elements/with-children","value":{"type":"Switch","props":{"label":"Kids are coming","name":"with_children","checked":{"$bindState":"/inputs/request/with_children"}},"children":[]}}
{"op":"add","path":"/elements/budget","value":{"type":"NumberInput","props":{"label":"Total budget","name":"budget","value":{"$bindState":"/inputs/request/budget"}},"children":[]}}
{"op":"add","path":"/elements/currency","value":{"type":"Segmented","props":{"label":"Currency","name":"currency","options":["EUR","USD","GBP","JPY"],"value":{"$bindState":"/inputs/request/currency"}},"children":[]}}
{"op":"add","path":"/elements/group-feel","value":{"type":"FieldGroup","props":{"title":"How it should feel"},"children":["pace","style"]}}
{"op":"add","path":"/elements/pace","value":{"type":"Radio","props":{"label":"Pace","name":"pace","options":["slow","balanced","packed"],"value":{"$bindState":"/inputs/request/pace"},"checks":[{"type":"required","message":"Choose a pace"}]},"children":[]}}
{"op":"add","path":"/elements/style","value":{"type":"Segmented","props":{"label":"Mostly about","name":"style","options":["culture","food","nature","nightlife","family"],"value":{"$bindState":"/inputs/request/style"}},"children":[]}}
{"op":"add","path":"/elements/group-else","value":{"type":"FieldGroup","props":{"title":"Anything else"},"children":["accessibility","notes","inspiration"]}}
{"op":"add","path":"/elements/accessibility","value":{"type":"Input","props":{"label":"Access needs","name":"accessibility","placeholder":"Step-free routes, short walks","value":{"$bindState":"/inputs/request/accessibility"}},"children":[]}}
{"op":"add","path":"/elements/notes","value":{"type":"Textarea","props":{"label":"Notes for the planner","name":"notes","rows":4,"value":{"$bindState":"/inputs/request/notes"}},"children":[]}}
{"op":"add","path":"/elements/inspiration","value":{"type":"MthdsField","props":{"path":"/inputs/inspiration","label":"Inspiration image"},"children":[]}}
{"op":"add","path":"/elements/after-note","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm","align":"center"},"children":["returns-text","needs-text"]}}
{"op":"add","path":"/elements/returns-text","value":{"type":"Text","props":{"text":"You'll get a day-by-day plan, costs by category with an estimated total, and practical tips for getting around.","variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/needs-text","value":{"type":"Text","props":{"text":"The planner needs the trip details above to run.","variant":"caption"},"children":[]}}
